function extractText(json) {
  if (!json || typeof json !== 'object') return '';
  if (json.llm_response?.choices?.[0]?.message?.content) return json.llm_response.choices[0].message.content;
  if (json.choices?.[0]?.message?.content) return json.choices[0].message.content;
  if (typeof json.output === 'string') return json.output;
  if (typeof json.text === 'string') return json.text;
  if (typeof json.response === 'string') return json.response;
  if (typeof json.message?.content === 'string') return json.message.content;
  return JSON.stringify(json);
}

function cleanJsonText(text) {
  let s = String(text || '').trim();
  s = s.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start >= 0 && end > start) s = s.slice(start, end + 1);
  return s;
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  return [value];
}

function text(value) {
  return String(value ?? '').trim();
}

function normalizeChapterTitle(value, fallback = '') {
  const raw = text(value);
  const fallbackText = text(fallback);
  if (!raw) return fallbackText;
  const cleaned = raw
    .replace(/^第\s*(?:[0-9０-９]+|[一二三四五六七八九十百千万零〇两]+|[Xx]+)\s*章\s*[：:、，,.．。-]?\s*/, '')
    .trim();
  return cleaned || fallbackText || raw;
}

function splitLongNarration(value, maxLength = 120) {
  const source = text(value);
  if (!source) return [];
  const sentences = source.match(/[^。！？!?；;]+[。！？!?；;]+[”」』’]?|[^。！？!?；;]+$/g) || [source];
  const chunks = [];
  let current = '';

  for (const sentence of sentences) {
    const piece = sentence.trim();
    if (!piece) continue;
    if (current && (current.length + piece.length > maxLength || startsNewBeat(piece))) {
      chunks.push(current);
      current = '';
    }
    if (piece.length > maxLength * 1.5) {
      if (current) {
        chunks.push(current);
        current = '';
      }
      const clauses = piece.match(/[^，,、]+[，,、]?|[^，,、]+$/g) || [piece];
      let clauseBuffer = '';
      for (const clause of clauses) {
        const cleanedClause = clause.trim();
        if (!cleanedClause) continue;
        if (clauseBuffer && clauseBuffer.length + cleanedClause.length > maxLength) {
          chunks.push(clauseBuffer);
          clauseBuffer = cleanedClause;
        } else {
          clauseBuffer += cleanedClause;
        }
      }
      if (clauseBuffer) chunks.push(clauseBuffer);
      continue;
    }
    current += piece;
  }

  if (current) chunks.push(current);
  return chunks;
}

function splitDialoguePieces(sentence) {
  const source = text(sentence);
  if (!source) return [];
  const quotePattern = /[“「『][^”」』]{1,260}[”」』]/g;
  const pieces = [];
  let lastIndex = 0;
  let match;

  while ((match = quotePattern.exec(source)) !== null) {
    const before = source.slice(lastIndex, match.index).trim();
    const quote = match[0];
    const quoteInner = quote.slice(1, -1);
    const after = source.slice(match.index + quote.length).trim();
    const quoteLooksLikeDialogue =
      /[：:]$/.test(before) ||
      /[。！？!?]$/.test(quoteInner) ||
      quoteInner.length >= 14 ||
      /^(一声|两字|两个字|这句|这话)/.test(after);
    if (!quoteLooksLikeDialogue) continue;

    if (before) {
      const attachToQuote = /[：:]$/.test(before) && before.length <= 12;
      if (attachToQuote) {
        pieces.push(`${before}${quote}`);
      } else {
        pieces.push(...splitLongNarration(before, 120));
        pieces.push(quote);
      }
    } else {
      pieces.push(quote);
    }
    lastIndex = match.index + quote.length;
  }

  const tail = source.slice(lastIndex).trim();
  if (tail) pieces.push(...splitLongNarration(tail, 120));
  return pieces.length ? pieces : [source];
}

function isDialoguePiece(value) {
  return /^[“「『].+[”」』]$/.test(value) || /^[^。！？!?；;]{0,48}[：:][“「『]/.test(value);
}

function startsNewBeat(value) {
  return /^(这时|就在这时|突然|下一秒|与此同时|然而|可是|但|只是|不对|念头|前世|电话|手机|屏幕|门外|身后|空气|办公室|会议室|电梯|人群|协议书|合同|他|她|我|你|陆泽|沈清秋|方凯|赵强|苏雅)/.test(value);
}

function splitNarrativeUnits(paragraph) {
  const source = text(paragraph);
  if (!source) return [];
  const units = [];
  let current = '';

  function flush() {
    if (current.trim()) units.push(current.trim());
    current = '';
  }

  for (const piece of splitDialoguePieces(source)) {
    const pieces = isDialoguePiece(piece) ? [piece] : splitLongNarration(piece, 120);
    for (const candidate of pieces) {
      const cleaned = candidate.trim();
      if (!cleaned) continue;
      if (isDialoguePiece(cleaned)) {
        flush();
        units.push(cleaned);
        continue;
      }
      if (
        current &&
        (current.length + cleaned.length > 100 ||
          startsNewBeat(cleaned) ||
          /[”」』’]$/.test(current))
      ) {
        flush();
      }
      current += cleaned;
      if (current.length >= 120 || /[！？!?]$/.test(cleaned)) flush();
    }
  }

  flush();
  return units;
}

function normalizeNovelParagraphs(value) {
  const raw = text(value)
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (!raw) return '';

  const paragraphs = [];
  for (const block of raw.split(/\n+/).map((item) => item.trim()).filter(Boolean)) {
    for (const unit of splitNarrativeUnits(block)) {
      const chunks = isDialoguePiece(unit) ? [unit] : splitLongNarration(unit, 140);
      for (const chunk of chunks) {
        const cleaned = chunk.trim();
        if (cleaned) paragraphs.push(cleaned);
      }
    }
  }

  return paragraphs.join('\n');
}

function number(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function jsonArray(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
      return [];
    }
  }
  return [];
}

function maxChapterNo(value) {
  return jsonArray(value).reduce((max, item) => {
    const chapterNo = number(item?.chapter_no, 0);
    return chapterNo > max ? Math.round(chapterNo) : max;
  }, 0);
}

function assertOutlineCoverage(chapters, response) {
  const runType = text(response.run_type || response.job_type).toUpperCase();
  if (runType !== 'GENERATE_OUTLINE') return;
  const targetTotal = Math.round(number(response.target_total_chapters, 0));
  if (!targetTotal) return;

  const scope = text(response.expansion_scope || 'append_only');
  const approvedMax = maxChapterNo(response.approved_chapters);
  const existingMax = maxChapterNo(response.existing_outlines);
  const expectedStart = scope === 'regenerate_outline'
    ? 1
    : (scope === 'rewrite_unwritten'
      ? Math.max(1, approvedMax + 1)
      : Math.max(1, existingMax + 1));
  if (expectedStart > targetTotal) return;

  const chapterNumbers = new Set(chapters
    .map((chapter) => Math.round(number(chapter.chapter_no, 0)))
    .filter((chapterNo) => chapterNo > 0));
  const missing = [];
  for (let chapterNo = expectedStart; chapterNo <= targetTotal; chapterNo += 1) {
    if (!chapterNumbers.has(chapterNo)) missing.push(chapterNo);
  }
  if (missing.length) {
    const sample = missing.slice(0, 12).join('、');
    throw new Error(`大纲章节覆盖不足：目标总章数为 ${targetTotal}，扩写范围 ${scope} 必须覆盖第 ${expectedStart}-${targetTotal} 章；缺少第 ${sample}${missing.length > 12 ? ' 等' : ''}章。`);
  }
}

function assertNoPrematureFinale(chapters, response) {
  const runType = text(response.run_type || response.job_type).toUpperCase();
  if (runType !== 'GENERATE_OUTLINE') return;
  const targetTotal = Math.round(number(response.target_total_chapters, 0));
  if (!targetTotal || targetTotal <= 1) return;

  const finalePattern = /(大结局|全书完|全文完|全书完结|全剧终|主线收束|全书收束|故事落幕|落下帷幕|全书高潮收尾)/;
  const offenders = chapters
    .map((chapter) => {
      const chapterNo = Math.round(number(chapter.chapter_no, 0));
      const content = [
        chapter.title,
        chapter.summary,
        chapter.chapter_goal,
        chapter.conflict_point,
        chapter.emotional_point,
        chapter.hook,
      ].map((value) => text(value)).join('\n');
      return {chapterNo, content};
    })
    .filter((item) => item.chapterNo > 0 && item.chapterNo < targetTotal && finalePattern.test(item.content));

  if (offenders.length) {
    const sample = offenders.slice(0, 8).map((item) => `第 ${item.chapterNo} 章`).join('、');
    throw new Error(`大纲提前完结风险：目标总章数为 ${targetTotal}，但 ${sample} 出现终局式表达；除最后一章外不得写“大结局、全书完、主线收束、故事落幕”等提前完结信号。`);
  }
}

function score(value, fallback = 0, options = {}) {
  const parsed = number(value, fallback);
  const scaled = options.scaleTenPoint && parsed > 0 && parsed <= 10
    ? parsed * 10
    : parsed;
  return Math.min(Math.max(Math.round(scaled), 0), 100);
}

function shouldScaleTenPointScores(values) {
  const scores = values
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value));
  return scores.length > 0 && scores.every((value) => value >= 0 && value <= 10) && scores.some((value) => value > 0);
}

function base64Text(value) {
  return Buffer.from(String(value ?? ''), 'utf8').toString('base64');
}

const allowedFactTypes = new Set([
  'character',
  'item',
  'location',
  'ability',
  'relationship',
  'foreshadowing',
  'timeline',
  'rule',
  'other',
]);

function normalizeFactType(value, fallbackType = 'other') {
  const raw = text(value || fallbackType) || fallbackType;
  return allowedFactTypes.has(raw) ? raw : (allowedFactTypes.has(fallbackType) ? fallbackType : 'other');
}

function isMachineFactKey(value) {
  const raw = text(value);
  if (!raw || /[\u4e00-\u9fff]/.test(raw)) return false;
  return /^[a-z0-9_.:-]+$/i.test(raw) && /[a-z]/i.test(raw);
}

function factKeyFromValue(value, factType) {
  const source = text(value).replace(/\s+/g, ' ');
  const typeLabel = {
    character: '人物',
    item: '物品',
    location: '地点',
    ability: '能力',
    relationship: '关系',
    foreshadowing: '伏笔',
    timeline: '时间线',
    rule: '规则',
    other: '事实',
  }[factType] || '事实';
  if (!source) return typeLabel;
  const firstClause = source.split(/[。！？；;，,]/)[0].trim() || source;
  return `${typeLabel}：${firstClause.slice(0, 18)}${firstClause.length > 18 ? '…' : ''}`;
}

function normalizeFact(fact, fallbackType = 'other') {
  const factType = normalizeFactType(fact.fact_type || fact.type, fallbackType);
  const factValue = text(fact.fact_value || fact.value || fact.description || fact.content);
  const rawKey = text(fact.fact_key || fact.key || fact.name);
  const displayKey = rawKey.replace(/_/g, '：');
  return {
    fact_type: factType,
    fact_key: isMachineFactKey(rawKey) ? factKeyFromValue(factValue, factType) : (displayKey || factKeyFromValue(factValue, factType)),
    fact_value: factValue,
    confidence: Math.min(Math.max(number(fact.confidence, 0.8), 0), 1),
  };
}

